create or replace function catalog.add_product_conversion_unit(
  p_tenant_id uuid,
  p_product_id uuid,
  p_unit_name text,
  p_conversion_rate_to_base numeric
)
returns jsonb
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_actor_id uuid;
  v_unit_name text := btrim(coalesce(p_unit_name, ''));
  v_name_normalized text := catalog._normalize_measurement_unit_name(p_unit_name);
  v_product_unit_id uuid;
begin
  v_actor_id := auth.uid();
  if v_actor_id is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.manage_units') then
    raise exception 'permission denied: catalog.product.manage_units';
  end if;

  if not exists (
    select 1
    from catalog.products p
    where p.id = p_product_id
      and p.tenant_id = p_tenant_id
      and p.deleted_at is null
  ) then
    raise exception 'product not found';
  end if;

  perform catalog._ensure_product_has_base_unit(p_tenant_id, p_product_id);

  if v_name_normalized is null then
    raise exception 'validation_exception: Unit name must not be empty.';
  end if;
  if length(v_unit_name) > 80 then
    raise exception 'validation_exception: Unit name is too long.';
  end if;
  if p_conversion_rate_to_base is null or p_conversion_rate_to_base <= 0 then
    raise exception 'validation_exception: Conversion rate must be greater than zero.';
  end if;

  if exists (
    select 1
    from catalog.product_units pu
    where pu.tenant_id = p_tenant_id
      and pu.product_id = p_product_id
      and pu.is_active = true
      and pu.unit_name_normalized = v_name_normalized
  ) then
    raise exception 'duplicate product unit "%"', v_unit_name;
  end if;

  insert into catalog.product_units (
    tenant_id,
    product_id,
    unit_name,
    unit_name_normalized,
    is_base_unit,
    conversion_rate_to_base,
    is_active,
    updated_at
  )
  values (
    p_tenant_id,
    p_product_id,
    v_unit_name,
    v_name_normalized,
    false,
    p_conversion_rate_to_base,
    true,
    now()
  )
  returning id into v_product_unit_id;

  insert into catalog.product_change_history (tenant_id, product_id, action, payload, actor_id)
  values (
    p_tenant_id,
    p_product_id,
    'add_product_conversion_unit',
    jsonb_build_object('product_unit_id', v_product_unit_id, 'unit_name', v_unit_name, 'conversion_rate_to_base', p_conversion_rate_to_base),
    v_actor_id
  );

  return jsonb_build_object(
    'product_id', p_product_id,
    'unit', catalog._product_unit_json(v_product_unit_id)
  );
end;
$$;

create or replace function catalog.deactivate_product_conversion_unit(
  p_tenant_id uuid,
  p_product_id uuid,
  p_product_unit_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_actor_id uuid;
  v_unit record;
begin
  v_actor_id := auth.uid();
  if v_actor_id is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.manage_units') then
    raise exception 'permission denied: catalog.product.manage_units';
  end if;

  select *
  into v_unit
  from catalog.product_units pu
  where pu.id = p_product_unit_id
    and pu.product_id = p_product_id
    and pu.tenant_id = p_tenant_id;

  if v_unit.id is null then
    raise exception 'product unit not found';
  end if;
  if v_unit.is_base_unit then
    raise exception 'validation_exception: Base unit cannot be deactivated here.';
  end if;

  update catalog.product_units
  set is_active = false,
      updated_at = now()
  where id = p_product_unit_id;

  insert into catalog.product_change_history (tenant_id, product_id, action, payload, actor_id)
  values (
    p_tenant_id,
    p_product_id,
    'deactivate_product_conversion_unit',
    jsonb_build_object('product_unit_id', p_product_unit_id, 'unit_name', v_unit.unit_name),
    v_actor_id
  );

  return jsonb_build_object(
    'product_id', p_product_id,
    'unit', catalog._product_unit_json(p_product_unit_id)
  );
end;
$$;

create or replace function catalog.reactivate_product_conversion_unit(
  p_tenant_id uuid,
  p_product_id uuid,
  p_product_unit_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_actor_id uuid;
  v_unit record;
begin
  v_actor_id := auth.uid();
  if v_actor_id is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.manage_units') then
    raise exception 'permission denied: catalog.product.manage_units';
  end if;

  select *
  into v_unit
  from catalog.product_units pu
  where pu.id = p_product_unit_id
    and pu.product_id = p_product_id
    and pu.tenant_id = p_tenant_id;

  if v_unit.id is null then
    raise exception 'product unit not found';
  end if;
  if v_unit.is_base_unit then
    raise exception 'validation_exception: Base unit cannot be reactivated here.';
  end if;
  if v_unit.conversion_rate_to_base <= 0 then
    raise exception 'validation_exception: Conversion rate must be greater than zero.';
  end if;
  if exists (
    select 1
    from catalog.product_units pu
    where pu.tenant_id = p_tenant_id
      and pu.product_id = p_product_id
      and pu.id <> p_product_unit_id
      and pu.is_active = true
      and pu.unit_name_normalized = v_unit.unit_name_normalized
  ) then
    raise exception 'duplicate product unit "%"', v_unit.unit_name;
  end if;

  update catalog.product_units
  set is_active = true,
      updated_at = now()
  where id = p_product_unit_id;

  insert into catalog.product_change_history (tenant_id, product_id, action, payload, actor_id)
  values (
    p_tenant_id,
    p_product_id,
    'reactivate_product_conversion_unit',
    jsonb_build_object('product_unit_id', p_product_unit_id, 'unit_name', v_unit.unit_name),
    v_actor_id
  );

  return jsonb_build_object(
    'product_id', p_product_id,
    'unit', catalog._product_unit_json(p_product_unit_id)
  );
end;
$$;

-- Guard operational RPCs created by 02_catalog_operational_data.sql.
create or replace function catalog.set_initial_stock(
  p_tenant_id uuid,
  p_product_id uuid,
  p_mode text,
  p_initial_stock numeric
)
returns void
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_actor_id uuid;
begin
  v_actor_id := auth.uid();
  if v_actor_id is null then
    raise exception 'not authenticated';
  end if;
  if not iam.has_permission(p_tenant_id, 'catalog.product.manage_stock') then
    raise exception 'permission denied: catalog.product.manage_stock';
  end if;
  if not exists (select 1 from catalog.products where id = p_product_id and tenant_id = p_tenant_id) then
    raise exception 'product not found';
  end if;
  perform catalog._ensure_product_has_base_unit(p_tenant_id, p_product_id);
  if p_mode <> 'basic' then
    raise exception 'not_basic_stock_mode';
  end if;
  if p_initial_stock < 0 then
    raise exception 'validation_exception: initial stock cannot be negative';
  end if;

  insert into catalog.product_stock_profiles (product_id, tenant_id, mode, initial_stock, updated_at)
  values (p_product_id, p_tenant_id, p_mode, p_initial_stock, now())
  on conflict (product_id) do update set
    mode = excluded.mode,
    initial_stock = excluded.initial_stock,
    updated_at = now();

  insert into catalog.product_change_history (tenant_id, product_id, action, payload, actor_id)
  values (p_tenant_id, p_product_id, 'set_initial_stock', jsonb_build_object('mode', p_mode, 'initial_stock', p_initial_stock), v_actor_id);
end;
$$;

create or replace function catalog.set_manual_base_price(
  p_tenant_id uuid,
  p_product_id uuid,
  p_mode text,
  p_base_price numeric,
  p_currency text default 'VND'
)
returns void
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_actor_id uuid;
begin
  v_actor_id := auth.uid();
  if v_actor_id is null then
    raise exception 'not authenticated';
  end if;
  if not iam.has_permission(p_tenant_id, 'catalog.product.manage_pricing') then
    raise exception 'permission denied: catalog.product.manage_pricing';
  end if;
  if not exists (select 1 from catalog.products where id = p_product_id and tenant_id = p_tenant_id) then
    raise exception 'product not found';
  end if;
  perform catalog._ensure_product_has_base_unit(p_tenant_id, p_product_id);
  if p_mode <> 'manual' then
    raise exception 'not_manual_base_price_mode';
  end if;
  if p_base_price is not null and p_base_price < 0 then
    raise exception 'validation_exception: base price cannot be negative';
  end if;

  insert into catalog.product_base_price_profiles (product_id, tenant_id, mode, base_price_amount, currency, updated_at)
  values (p_product_id, p_tenant_id, p_mode, p_base_price, coalesce(p_currency, 'VND'), now())
  on conflict (product_id) do update set
    mode = excluded.mode,
    base_price_amount = excluded.base_price_amount,
    currency = excluded.currency,
    updated_at = now();

  insert into catalog.product_change_history (tenant_id, product_id, action, payload, actor_id)
  values (p_tenant_id, p_product_id, 'set_manual_base_price', jsonb_build_object('mode', p_mode, 'base_price', p_base_price, 'currency', p_currency), v_actor_id);
end;
$$;

create or replace function catalog.set_initial_price_band(
  p_tenant_id uuid,
  p_product_id uuid,
  p_list_price numeric,
  p_floor_price numeric,
  p_product_unit_id uuid default null
)
returns void
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_actor_id uuid;
  v_product_unit_id uuid;
begin
  v_actor_id := auth.uid();
  if v_actor_id is null then
    raise exception 'not authenticated';
  end if;
  if not iam.has_permission(p_tenant_id, 'catalog.product.manage_pricing') then
    raise exception 'permission denied: catalog.product.manage_pricing';
  end if;
  if not exists (select 1 from catalog.products where id = p_product_id and tenant_id = p_tenant_id) then
    raise exception 'product not found';
  end if;
  perform catalog._ensure_product_has_base_unit(p_tenant_id, p_product_id);
  if p_floor_price is not null and p_list_price is not null and p_floor_price > p_list_price then
    raise exception 'floor_price_greater_than_list_price';
  end if;

  v_product_unit_id := p_product_unit_id;
  if v_product_unit_id is null then
    select pu.id into v_product_unit_id
    from catalog.product_units pu
    where pu.product_id = p_product_id
      and pu.tenant_id = p_tenant_id
      and pu.is_base_unit = true
    limit 1;
  end if;
  if v_product_unit_id is null then
    raise exception 'missing base unit';
  end if;

  insert into catalog.product_unit_price_bands (tenant_id, product_id, product_unit_id, list_price_amount, floor_price_amount, updated_at)
  values (p_tenant_id, p_product_id, v_product_unit_id, p_list_price, p_floor_price, now())
  on conflict (product_id, product_unit_id) do update set
    list_price_amount = excluded.list_price_amount,
    floor_price_amount = excluded.floor_price_amount,
    updated_at = now();

  insert into catalog.product_change_history (tenant_id, product_id, action, payload, actor_id)
  values (p_tenant_id, p_product_id, 'set_initial_price_band', jsonb_build_object('product_unit_id', v_product_unit_id, 'list_price', p_list_price, 'floor_price', p_floor_price), v_actor_id);
end;
$$;

